actions.new_string:
def create_database(
    self, database_name: str, database_input: Dict[str, Any], tags: Optional[Dict[str, str]] = None
) -> "FakeDatabase":
    if database_name in self.databases:
        raise DatabaseAlreadyExistsException()

    database = FakeDatabase(
        database_name, database_input, catalog_id=self.account_id
    )
    self.databases[database_name] = database

    # Apply tags if provided
    if tags:
        database_arn = f"arn:aws:glue:{self.region}:{self.account_id}:database/{database_name}"
        self.tag_resource(database_arn, tags)

    return database
